import type { Objective } from '@/entities/objective/types'
import { MemberPill } from '@/shared/ui/MemberPill'
import { RoleBadge } from '@/shared/ui/RoleBadge'
import { UserPlus } from 'lucide-react'

type Props = { objective: Objective }
const VALUE_MODES = ['fixed', 'variable', 'milestone', 'none'] as const

export function AssignTab({ objective }: Props) {
  const owners = objective.participants.filter((p) => p.role === 'owner')
  const contributors = objective.participants.filter((p) => p.role === 'contributor')
  const evaluators = objective.participants.filter((p) => p.role === 'evaluator')
  const viewers = objective.participants.filter((p) => p.role === 'viewer')

  const roleGroups = [
    { label: 'Owners', members: owners, role: 'owner' as const },
    { label: 'Contributors', members: contributors, role: 'contributor' as const },
    { label: 'Evaluators', members: evaluators, role: 'evaluator' as const },
    { label: 'Viewers', members: viewers, role: 'viewer' as const },
  ]

  return (
    <div className="p-6 max-w-2xl mx-auto">
      <div className="bg-surface rounded-xl border border-border p-6 flex flex-col gap-6">
        {roleGroups.map((group) => (
          <div key={group.role}>
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs text-muted-foreground font-medium uppercase tracking-wide">{group.label}</label>
              <button className="text-xs text-accent flex items-center gap-1 hover:underline"><UserPlus size={12} /> Add</button>
            </div>
            <div className="flex flex-wrap gap-2">
              {group.members.map((m) => (
                <div key={m.userId} className="flex items-center gap-1.5">
                  <MemberPill member={m} />
                  <RoleBadge status={m.agreementStatus} />
                </div>
              ))}
              {group.members.length === 0 && <p className="text-xs text-muted-foreground italic">No {group.label.toLowerCase()} assigned</p>}
            </div>
          </div>
        ))}
        <div className="border-t border-border pt-5">
          <label className="text-xs text-muted-foreground font-medium uppercase tracking-wide block mb-3">Value assignment</label>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-sm font-medium block mb-1.5">Value mode</label>
              <select defaultValue={objective.valueMode} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent">
                {VALUE_MODES.map((m) => <option key={m} value={m}>{m.charAt(0).toUpperCase() + m.slice(1)}</option>)}
              </select>
            </div>
            <div>
              <label className="text-sm font-medium block mb-1.5">Assigned value ({objective.currency})</label>
              <input type="number" defaultValue={objective.assignedValue} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
            </div>
          </div>
        </div>
        <div className="flex justify-end">
          <button className="bg-accent text-accent-foreground px-4 py-2 rounded-lg text-sm hover:opacity-90">Save assignments</button>
        </div>
      </div>
    </div>
  )
}
